const priorityText={high:'高优先级',medium:'中优先级',low:'背景关注'};
const scopeText={'control-judgment':'议院控制权',state:'州级',race:'单场选举',admin:'选务管理'};
const qualityText={'primary-verified':'原始来源已核验','primary-filing-verified':'原始来源已核验','reported-primary-order-missing':'报道已核验；法院命令待核验','publisher-snapshot-verified':'机构快照已核验'};
const freshnessText={'already-in-baseline':'基线已收录','post-baseline-report':'基线后的新报道','newly-added-before-baseline':'新增收录；事件早于基线','newly-added-publication-time-unknown':'新增收录；精确发布时间未知'};
export function newsEntries(evidence,{priority='all',scope='all'}={}){return(evidence.news||[]).filter(n=>(priority==='all'||n.annotation?.priority===priority)&&(scope==='all'||n.annotation?.impactScope?.includes(scope))).sort((a,b)=>({high:0,medium:1,low:2}[a.annotation?.priority]??3)-({high:0,medium:1,low:2}[b.annotation?.priority]??3)||String(b.date).localeCompare(String(a.date)));}
const date=(value,esc)=>value?esc(value):'待核验';
const source=(url,esc)=>`<a href="${esc(url)}" target="_blank" rel="noopener">原始来源 ↗</a>`;
const badge=(a,esc)=>`<span class="impact-priority priority-${a.priority||'low'}">${esc(priorityText[a.priority]||'待核验')}</span><span class="impact-control">${a.controlJudgment==='unchanged'?'控制权判断未变':'待核验'}</span>`;
const scopes=(a,esc)=>(a.impactScope||[]).map(x=>esc(scopeText[x]||x)).join(' · ');
export function newsHTML(evidence,filters,esc){return newsEntries(evidence,filters).map(n=>{const a=n.annotation||{};return `<article class="impact-news" data-news-id="${esc(n.id||'')}" data-priority="${esc(a.priority)}"><div class="impact-badges">${badge(a,esc)}</div><h3><a href="${esc(n.source)}" target="_blank" rel="noopener">${esc(n.title)} ↗</a></h3><p class="impact-scope">影响范围：${scopes(a,esc)} ${(a.affected?.states||[]).map(esc).join(' · ')}</p><p>${esc(n.summary)}</p><div class="evidence-status"><strong>${esc(qualityText[a.evidenceQuality?.level]||'待核验')}</strong><p>${esc(a.evidenceQuality?.note||n.status)}</p></div><p class="news-interpretation"><b>方向解读 · 本站解读</b><br>${esc(n.interpretation)}</p><p class="small">${esc(a.priorityReason)}</p><details class="impact-review"><summary>时间与下一步核验</summary><dl><dt>事件 / 调查日期</dt><dd>${a.fieldStart?date(a.fieldStart,esc)+' — '+date(a.fieldEnd,esc):date(a.eventDate,esc)}</dd><dt>发布</dt><dd>${date(a.publishedAt||a.publishedDate,esc)}</dd><dt>核验</dt><dd>${date(a.reviewedAt,esc)}</dd></dl><p>${esc(freshnessText[a.freshness]||'')}</p><p><strong>下一步核验</strong><br>${esc(a.recheckTrigger)}</p>${source(n.source,esc)}</details></article>`;}).join('')||'<p class="trend-blank">暂无匹配条目</p>';}
export function interpretationHTML(evidence,esc){return `<div class="section-top"><div><p class="eyebrow">EVIDENCE & INTERPRETATION</p><h2>证据改变了什么</h2></div><span class="tag">定性判断，非概率预测</span></div><p class="muted">事实、机构评级与本站条件性解读分开。未取得证据，不等于没有变化。</p><div class="interpretation-grid">${(evidence.interpretationCards||[]).map(c=>`<article class="interpretation-card" id="interpretation-${esc(c.id)}"><div class="impact-badges">${badge(c,esc)}</div><h3>${esc(c.title)}</h3><div class="interpretation-step confirmed"><b>已核验事实</b><p>${esc(c.confirmedChange)}</p></div><div class="interpretation-step"><b>可能影响 · 本站解读</b><p>${esc(c.possibleEffect)}</p></div><div class="interpretation-step uncertain"><b>反向证据 / 未知</b><p>${esc(c.counterevidenceOrUnknown)}</p></div><div class="interpretation-step next"><b>下一步核验</b><p>${esc(c.nextCheck)}</p></div><footer><span>核验 ${esc(c.asOf)}</span>${(c.sources||[]).map(url=>source(url,esc)).join(' · ')}</footer></article>`).join('')}</div>`;}
export function renderNewsImpact(evidence,esc){const panel=document.querySelector('#news');panel.parentElement.classList.add('news-panel');document.querySelector('.two-cols').classList.add('impact-columns');let filters=document.querySelector('#news-filters');if(!filters){filters=document.createElement('div');filters.id='news-filters';filters.innerHTML=`<p class="small muted">优先级表示值得关注的程度，不代表确定性、警报或预期票差变化。</p><div class="news-filter-row"><label>关注优先级 <select id="news-priority"><option value="all">全部</option>${Object.entries(priorityText).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>影响范围 <select id="news-scope"><option value="all">全部</option>${Object.entries(scopeText).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><p id="news-result-count" role="status" class="small"></p>`;panel.before(filters);}const render=()=>{const f={priority:document.querySelector('#news-priority').value,scope:document.querySelector('#news-scope').value};panel.innerHTML=newsHTML(evidence,f,esc);document.querySelector('#news-result-count').textContent=`${newsEntries(evidence,f).length} / ${(evidence.news||[]).length}`;};filters.querySelectorAll('select').forEach(x=>x.onchange=render);render();let interpretation=document.querySelector('#interpretation');if(!interpretation){interpretation=document.createElement('section');interpretation.id='interpretation';document.querySelector('#evidence').before(interpretation);}interpretation.innerHTML=interpretationHTML(evidence,esc);let outlook=document.querySelector('#forecast-evidence');if(!outlook){outlook=document.createElement('div');outlook.id='forecast-evidence';document.querySelector('#changes').append(outlook);}outlook.innerHTML=(evidence.forecastAnnotations||[]).map(a=>`<article class="forecast-evidence-card"><h3>${a.target==='summary.senate'?'RCP 参院评级总览':'RCP 众院评级总览'}</h3><div class="impact-badges">${badge(a,esc)}</div><p>${esc(a.evidenceQuality.note)}</p><p class="small">核验 ${esc(a.observedAt)} · 发布 ${date(a.publishedAt,esc)}</p><a href="#interpretation-${esc(a.interpretationCardId)}">本站解读 ↓</a><details><summary>下一步核验</summary><p>${esc(a.recheckTrigger)}</p>${source(a.source,esc)}</details></article>`).join('');}
